func TestDump(t *testing.T) {
	for _, c := range dumpCases {
		data, err := Load(c.doc)
		if err != nil {
			t.Fatalf("%s: %v", c.name, err)
		}
		got, err := Dump(data, c.opts)
		if err != nil {
			t.Fatalf("%s: %v", c.name, err)
		}
		if got != c.want {
			t.Errorf("%s:\n got %q\nwant %q", c.name, got, c.want)
		}
	}
}

