func TestQuoted(t *testing.T) {
	for _, c := range quotedCases {
		if got := Quoted(c.value); got != c.want {
			t.Errorf("Quoted(%q):\n got %q\nwant %q", c.value, got, c.want)
		}
	}
}

func TestDumpUnrepresentable(t *testing.T) {
	if _, err := Dump(struct{}{}, DumpOptions{}); err == nil {
		t.Fatal("書き出せない型を通した")
	}
}

// 上の段が組む値（Put で並べたマップと []string）も、読んだ値と同じ形で書く。
func TestDumpBuiltMap(t *testing.T) {
	m := &Map{}
	m.Put("ticket", "x")
	m.Put("predecessors", []string{})
	m.Put("allow", []any{[]string{"a"}})
	m.Put("ticket", "y")
	got, err := Dump(m, DumpOptions{})
	if want := "ticket: y\npredecessors: []\nallow:\n- - a\n"; err != nil || got != want {
		t.Errorf("%q, %v", got, err)
	}
}
